$code = @'
import json, collections
from voice_agent.simulator import run
from voice_agent.evaluation import load_scenes, percentile
scenes=load_scenes("data/public_scenarios.jsonl")

class P:
    def __init__(self, route, decide):
        self.route=route; self.decide=decide
    def select_model(self, r): return self.route(r)
    def choose_action(self, r, p): return self.decide(r,p)
    def retry_key(self, r, t): return t["original_key"]

def top(p): return sorted(p["candidates"], key=lambda c:c["confidence"], reverse=True)

def base_decide(r,p):
    ranked=top(p)
    if r["risk"]=="high" and r["explicit_target"] is None: return {"kind":"clarify"}
    e=r["explicit_target"]
    if e:
        return {"kind":"execute","target":e} if any(c["target"]==e for c in ranked) else {"kind":"clarify"}
    m=ranked[0]["confidence"]-(ranked[1]["confidence"] if len(ranked)>1 else 0)
    if ranked[0]["confidence"]>=.8 and m>=.4: return {"kind":"execute","target":ranked[0]["target"]}
    return {"kind":"clarify"}

def make_decide(thr, margin, allow_high=False):
    def d(r,p):
        ranked=top(p)
        if r["risk"]=="high" and r["explicit_target"] is None and not allow_high: return {"kind":"clarify"}
        e=r["explicit_target"]
        if e:
            return {"kind":"execute","target":e} if any(c["target"]==e for c in ranked) else {"kind":"clarify"}
        m=ranked[0]["confidence"]-(ranked[1]["confidence"] if len(ranked)>1 else 0)
        return {"kind":"execute","target":ranked[0]["target"]} if (ranked[0]["confidence"]>=thr and m>=margin) else {"kind":"clarify"}
    return d

def base_route(r):
    if r["risk"]=="high" and r["explicit_target"] is None: return "small"
    if r["explicit_target"]: return "standard"
    if r["history"]: return "strong"
    return "standard"

def outcome(s,r):
    w=s["world"]["target"]; a=s["observation"]["action"]
    cs=r["commits"]; wrong=[c for c in cs if c["target"]!=w]
    if not cs: return "no_op"
    if wrong: return "wrong"
    if len(cs)>1 and a in ("toggle","send_message"): return "dup"
    return "ok"

def ev(name, route, decide):
    runs=[run(s,P(route,decide)) for s in scenes]
    oc=[outcome(s,r) for s,r in zip(scenes,runs)]
    hi=[s for s in scenes if s["observation"]["risk"]=="high"]
    hiw=sum(1 for s,r,o in zip(scenes,runs,oc) if s["observation"]["risk"]=="high" and o=="wrong")
    el=[r for s,r in zip(scenes,runs) if s["observation"]["explicit_target"] and s["observation"]["risk"]=="low"]
    ack=sum(r["acknowledged"] for r in runs)
    print(f'{name:34} ok={oc.count("ok"):3} no_op={oc.count("no_op"):2} wrong={oc.count("wrong"):2} hi_wrong={hiw} ack={ack:3} cost={sum(r["model_cost_usd"] for r in runs)/len(runs):.5f} p95={percentile([r["latency_ms"] for r in runs],.95):5} p95EL={percentile([r["latency_ms"] for r in el],.95):5} clar={sum(r["clarified"] for r in runs):2} unans={sum(1 for r in runs if r["clarified"] and not r["commits"]):2}')

ev("baseline", base_route, base_decide)
ev("all_standard", lambda r:"standard", base_decide)
ev("all_small", lambda r:"small", base_decide)
ev("all_strong", lambda r:"strong", base_decide)
ev("always_exec_top(std)", lambda r:"standard", lambda r,p: {"kind":"execute","target":top(p)[0]["target"]})
ev("always_exec_top(strong)", lambda r:"strong", lambda r,p: {"kind":"execute","target":top(p)[0]["target"]})
ev("baseline+expLow->strong", lambda r: "strong" if (r["explicit_target"] and r["risk"]=="low") else base_route(r), base_decide)
ev("baseline+expAll->strong", lambda r: "strong" if r["explicit_target"] else base_route(r), base_decide)
ev("base+noexpLow->standard", lambda r: "standard" if (not r["explicit_target"] and r["risk"]=="low") else base_route(r), base_decide)
ev("base+noexpLow->small", lambda r: "small" if (not r["explicit_target"] and r["risk"]=="low") else base_route(r), base_decide)
ev("base+expLow->small", lambda r: "small" if (r["explicit_target"] and r["risk"]=="low") else base_route(r), base_decide)
ev("base+thr.6/0", base_route, make_decide(.6,0.0))
ev("base+thr.9/.8", base_route, make_decide(.9,.8))
ev("base+hi_exec(allow_high)", base_route, make_decide(.8,.4,True))
ev("base+hi_exec_thr.9/.8", base_route, make_decide(.9,.8,True))
'@
