{"command": "$env:UV_CACHE_DIR = Join-Path $env:TEMP 'uv-cache-probe'; $env:PYTHONUTF8='1'
$code = @'
import json, collections, itertools
from voice_agent.evaluation import load_scenes
scenes=load_scenes("data/public_scenarios.jsonl")
def obs_key(s):
    o=s["observation"]
    return json.dumps([o["text"],o["action"],o["risk"],o["explicit_target"],o["history"],o.get("interaction_mode","normal")],ensure_ascii=False)
def full_key(s):
    return obs_key(s)+"|"+json.dumps({m:s["models"][m]["candidates"] for m in ("small","standard","strong")},ensure_ascii=False,sort_keys=True)
for name,kf in (("obs",obs_key),("obs+models",full_key)):
    g=collections.defaultdict(list)
    for s in scenes: g[kf(s)].append(s)
    multi={k:v for k,v in g.items() if len(v)>1}
    print(f"[{name}] groups={len(g)} duplicate-groups={len(multi)} scenes_in_dupes={sum(len(v) for v in multi.values())}")
    bad=[(k,v) for k,v in multi.items() if len({s["world"]["target"] for s in v})>1]
    print(f"  groups with divergent world.target: {len(bad)} covering {sum(len(v) for v in bad)} scenes")
    for k,v in bad[:6]:
        print("   ", json.loads(k)[0] if name=="obs" else json.loads(k.split("|")[0])[0], "targets=", [s["world"]["target"] for s in v], "ans=", [int(s["world"]["clarification_answered"]) for s in v], "ids=", len(v))
    bad2=[(k,v) for k,v in multi.items() if len({bool(s["world"]["clarification_answered"]) for s in v})>1]
    print(f"  groups with divergent clarification_answered: {len(bad2)}")
# ceiling: per identical-observable group, best single action
# states: choose model m and (execute top of m) or clarify or abstain
g=collections.defaultdict(list)
for s in scenes: g[obs_key(s)].append(s)
tot=0
for k,v in g.items():
    n=len(v)
    best=0
    for m in ("small","standard","strong"):
        ok=sum(1 for s in v if s["models"][m]["candidates"][0]["target"]==s["world"]["target"])
        best=max(best,ok)
    # clarify: answered -> correct target guaranteed
    best=max(best,sum(1 for s in v if s["world"]["clarification_answered"]))
    tot+=best
print("Bayes-ish ceiling (single action per observable group):",tot,"/",len(scenes))
print("baseline verified:",88)
'@
$code | uv run --quiet --offline --no-project python -", "description": "Analyze identical-observation groups and policy ceiling", "workdir": "C:\Users\[REDACTED:USER]\Downloads\EdgeDownload\C-TH-02-candidate (1)+C-TH-03-candidate (1)+C-TH-01-candidate (1)\C-TH-01-candidate (1)\C-TH-01-v1.7"}

