import json, collections
from copy import deepcopy
from voice_agent.simulator import MODELS, validate
from voice_agent import policy
from voice_agent.evaluation import load_scenes, percentile
scenes=load_scenes("data/public_scenarios.jsonl")

def run_boundary(scene, policy, trust_explicit=False):
    validate(scene)
    obs, world = deepcopy(scene["observation"]), scene["world"]
    events=[]; model=policy.select_model(deepcopy(obs)); timing=MODELS[model]
    latency,cost=timing["latency_ms"],timing["cost_usd"]
    prediction=deepcopy(scene["models"][model])
    events.append({"type":"model","model":model,"prediction":prediction})
    d=policy.choose_action(deepcopy(obs),deepcopy(prediction)); kind=d.get("kind")
    clarified=kind=="clarify"; target=None; ack=False
    if clarified:
        latency += 1200 if obs.get("interaction_mode")=="busy" else 600
        if world["clarification_answered"]: target=world["target"]
    elif kind=="execute":
        target=d["target"]
        cands=[c["target"] for c in prediction["candidates"]]
        if target not in cands and not (trust_explicit and target==obs.get("explicit_target")):
            raise ValueError("execute target not in candidates")
    commits=[]; seen=set(); first_key=obs["request_id"]+":action"
    def commit(key):
        if key in seen: return
        seen.add(key); commits.append({"target":target,"action":obs["action"],"key":key})
    if target is not None:
        mode=world["timeout"]; latency += 80 if mode=="none" else 500
        if mode!="before_commit": commit(first_key)
        if mode=="none": ack=True
        else:
            rk=policy.retry_key(deepcopy(obs),{"original_key":first_key,"target":target,"attempt":1})
            if rk is not None: latency+=80; commit(rk); ack=True
    return {"id":scene["id"],"latency_ms":latency,"model_cost_usd":cost,"clarified":clarified,"acknowledged":ack,"commits":commits}

class Trust(policy.__class__ if False else object):
    pass
def mk_route(route): return route
class P:
    def __init__(self, route=None, decide=None):
        self.route=route or (lambda r: policy.select_model(r))
        self.decide=decide or (lambda r,p: policy.choose_action(r,p))
    def select_model(self,r): return self.route(r)
    def choose_action(self,r,p): return self.decide(r,p)
    def retry_key(self,r,t): return policy.retry_key(r,t)

def trust_decide(r,p):
    d=policy.choose_action(r,p)
    if d["kind"]=="clarify" and r.get("explicit_target"):
        return {"kind":"execute","target":r["explicit_target"]}
    return d
def ok(s,r): return len(r["commits"])==1 and r["commits"][0]["target"]==s["world"]["target"]
def report(name, route, decide, trust):
    pol=P(route,decide)
    runs=[run_boundary(s,pol,trust) for s in scenes]
    oc=[]
    for s,r in zip(scenes,runs):
        if not r["commits"]: oc.append("no_op")
        elif any(c["target"]!=s["world"]["target"] for c in r["commits"]): oc.append("wrong")
        else: oc.append("ok")
    hiw=sum(1 for s,r,o in zip(scenes,runs,oc) if s["observation"]["risk"]=="high" and o=="wrong")
    EL=[(s,r) for s,r in zip(scenes,runs) if s["observation"]["explicit_target"] and s["observation"]["risk"]=="low"]
    print(f'{name:26} ok={oc.count("ok")} no_op={oc.count("no_op")} wrong={oc.count("wrong")} hi_wrong={hiw} ack={sum(r["acknowledged"] for r in runs)} cost={sum(r["model_cost_usd"] for r in runs)/100:.5f} clar={sum(r["clarified"] for r in runs)} p95={percentile([r["latency_ms"] for r in runs],.95)} p95EL={percentile([r["latency_ms"] for s,r in EL],.95)}')
    return runs
r0=report("baseline(official)", None, None, False)
r1=report("boundary: trust explicit", None, trust_decide, True)
r2=report("contract: explicit->strong", lambda r: "strong" if r.get("explicit_target") else policy.select_model(r), None, False)
EL=[(s,r) for s,r in zip(scenes,r0) if s["observation"]["explicit_target"] and s["observation"]["risk"]=="low"]
print("EL latencies baseline", sorted(collections.Counter(r["latency_ms"] for s,r in EL).items()))
EL2=[(s,r) for s,r in zip(scenes,r1) if s["observation"]["explicit_target"] and s["observation"]["risk"]=="low"]
print("EL latencies boundary", sorted(collections.Counter(r["latency_ms"] for s,r in EL2).items()))
print("changed scenes:", [(s["id"],s["observation"]["text"],policy.select_model(s["observation"]),r0i["latency_ms"],r1i["latency_ms"],ok(s,r0i),ok(s,r1i)) for s,r0i,r1i in zip(scenes,r0,r1) if r0i["latency_ms"]!=r1i["latency_ms"] or ok(s,r0i)!=ok(s,r1i)])
